  "components": {
    "securitySchemes": {
      "bearer": {
        "scheme": "bearer",
        "bearerFormat": "JWT",
        "type": "http"
      }
    },
    "schemas": {
      "LoginDto": {
        "type": "object",
        "properties": {
          "idToken": {
            "type": "string",
            "description": "CipherBox-issued JWT identity token",
            "example": "eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9..."
          },
          "publicKey": {
            "type": "string",
            "description": "secp256k1 public key exported from Core Kit after loginWithJWT (uncompressed, 130 hex chars), or a placeholder \"pending-core-kit-{userId}\" for REQUIRED_SHARE temp auth",
            "example": "04abc123..."
          },
          "loginType": {
            "type": "string",
            "description": "Type of login used (always corekit)",
            "enum": ["corekit"],
            "example": "corekit"
          }
        },
        "required": ["idToken", "publicKey", "loginType"]
      },
      "LoginResponseDto": {
        "type": "object",
        "properties": {
          "accessToken": {
            "type": "string",
            "description": "JWT access token for API requests",
            "example": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..."
          },
          "isNewUser": {
            "type": "boolean",
            "description": "Whether this is a new user registration",
            "example": false
          },
          "refreshToken": {
            "type": "string",
            "description": "Refresh token (only present for desktop clients using X-Client-Type: desktop header)",
            "example": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..."
          }
        },
        "required": ["accessToken", "isNewUser"]
      },
      "DesktopRefreshDto": {
        "type": "object",
        "properties": {
          "refreshToken": {
            "type": "string",
            "description": "Refresh token from previous login/refresh (required for desktop clients)",
            "example": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..."
          }
        }
      },
      "TokenResponseDto": {
        "type": "object",
        "properties": {
          "accessToken": {
            "type": "string",
            "description": "New JWT access token",
            "example": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..."
          },
          "refreshToken": {
            "type": "string",
            "description": "New refresh token (only present for desktop clients using X-Client-Type: desktop header)",
            "example": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..."
          },
          "email": {
            "type": "string",
            "description": "User email from their most recently used email auth method",
            "example": "user@example.com"
          }
        },
        "required": ["accessToken"]
      },
      "LogoutResponseDto": {
        "type": "object",
        "properties": {
          "success": {
            "type": "boolean",
            "description": "Whether logout was successful",
            "example": true
          }
        },
        "required": ["success"]
      },
      "DeleteAccountDto": {
        "type": "object",
        "properties": {
          "confirmation": {
            "type": "string",
            "description": "Must be the string \"DELETE\" to confirm account deletion",
            "example": "DELETE"
          }
        },
        "required": ["confirmation"]
      },
      "DeleteAccountResponseDto": {
        "type": "object",
        "properties": {
          "success": {
            "type": "boolean",
            "description": "Whether the account was successfully deleted"
          }
        },
        "required": ["success"]
      },
      "AuthMethodResponseDto": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string"
          },
          "type": {
            "type": "string",
            "enum": ["google", "apple", "github", "email", "wallet"]
          },
          "identifier": {
            "type": "string",
            "description": "Email or wallet address"
          },
          "lastUsedAt": {
            "format": "date-time",
            "type": "string",
            "nullable": true
          },
          "createdAt": {
            "format": "date-time",
            "type": "string"
          }
        },
        "required": ["id", "type", "identifier", "lastUsedAt", "createdAt"]
      },
      "LinkMethodDto": {
        "type": "object",
        "properties": {
          "idToken": {
            "type": "string",
            "description": "CipherBox-issued JWT identity token (required for Google/email, not used for wallet)"
          },
          "loginType": {
            "type": "string",
            "description": "Auth method type to link",
            "enum": ["google", "email", "wallet"]
          },
          "walletAddress": {
            "type": "string",
            "description": "Wallet address (required when loginType is wallet)"
          },
          "siweMessage": {
            "type": "string",
            "description": "SIWE message (required when loginType is wallet)"
          },
          "siweSignature": {
            "type": "string",
            "description": "SIWE signature (required when loginType is wallet)"
          }
        },
        "required": ["idToken", "loginType"]
      },
      "UnlinkMethodDto": {
        "type": "object",
        "properties": {
          "methodId": {
            "type": "string"
          }
        },
        "required": ["methodId"]
      },
      "UnlinkMethodResponseDto": {
        "type": "object",
        "properties": {
          "success": {
            "type": "boolean"
          }
        },
        "required": ["success"]
      },
      "TestLoginDto": {
        "type": "object",
        "properties": {
          "email": {
            "type": "string",
            "description": "Email address for the test user"
          },
          "secret": {
            "type": "string",
            "description": "Secret that must match TEST_LOGIN_SECRET env var"
          }
        },
        "required": ["email", "secret"]
      },
      "TestLoginResponseDto": {
        "type": "object",
        "properties": {
          "accessToken": {
            "type": "string",
            "description": "JWT access token"
          },
          "refreshToken": {
            "type": "string",
            "description": "Refresh token"
          },
          "isNewUser": {
            "type": "boolean",
            "description": "Whether this is a newly created user"
          },
          "publicKeyHex": {
            "type": "string",
            "description": "Uncompressed secp256k1 public key (hex, 130 chars)"
          },
          "privateKeyHex": {
            "type": "string",
            "description": "secp256k1 private key (hex, 64 chars)"
          }
        },
        "required": ["accessToken", "refreshToken", "isNewUser", "publicKeyHex", "privateKeyHex"]
      },
      "GoogleLoginDto": {
        "type": "object",
        "properties": {
          "idToken": {
            "type": "string",
            "description": "Google OAuth ID token (from Google Sign-In)",
            "example": "eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9..."
          },
          "intent": {
            "type": "string",
            "description": "Intent: \"login\" (default) creates/finds a user, \"link\" only verifies ownership",
            "enum": ["login", "link"]
          }
        },
        "required": ["idToken"]
      },
      "IdentityTokenResponseDto": {
        "type": "object",
        "properties": {
          "idToken": {
            "type": "string",
            "description": "CipherBox-signed RS256 JWT for Web3Auth custom verifier (sub=userId)",
            "example": "eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9..."
          },
          "userId": {
            "type": "string",
            "description": "CipherBox internal user UUID",
            "example": "a1b2c3d4-e5f6-7890-abcd-ef1234567890"
          },
          "isNewUser": {
            "type": "boolean",
            "description": "Whether this is a newly created user",
            "example": false
          },
          "email": {
            "type": "string",
            "description": "Verified email address from the identity provider",
            "example": "user@example.com"
          }
        },
        "required": ["idToken", "userId", "isNewUser"]
      },
      "SendOtpDto": {
        "type": "object",
        "properties": {
          "email": {
            "type": "string",
            "description": "Email address to send OTP to",
            "example": "user@example.com"
          }
        },
        "required": ["email"]
      },
      "SendOtpResponseDto": {
        "type": "object",
        "properties": {
          "success": {
            "type": "boolean",
            "description": "Whether the OTP was sent successfully",
            "example": true
          }
        },
        "required": ["success"]
      },
      "VerifyOtpDto": {
        "type": "object",
        "properties": {
          "email": {
            "type": "string",
            "description": "Email address the OTP was sent to",
            "example": "user@example.com"
          },
          "otp": {
            "type": "string",
            "description": "6-digit OTP code",
            "example": "123456"
          },
          "intent": {
            "type": "string",
            "description": "Intent: \"login\" (default) creates/finds a user, \"link\" only verifies ownership",
            "enum": ["login", "link"]
          }
        },
        "required": ["email", "otp"]
      },
      "WalletVerifyDto": {
        "type": "object",
        "properties": {
          "message": {
            "type": "string",
            "description": "EIP-4361 SIWE message string",
            "example": "example.com wants you to sign in with your Ethereum account..."
          },
