            "description": "Hex-encoded ECIES ciphertext of the new key wrapped for recipient"
          }
        },
        "required": ["encryptedKey"]
      },
      "InviteStatusResponseDto": {
        "type": "object",
        "properties": {
          "status": {
            "type": "string",
            "enum": ["active"],
            "description": "Invite status. Only \"active\" is returned; all other states result in 404 to prevent token-existence oracle attacks."
          }
        },
        "required": ["status"]
      },
      "InviteChildKeyDto": {
        "type": "object",
        "properties": {
          "keyType": {
            "type": "string",
            "description": "Type of key: file, folder, or file-ipns",
