            "type": "string",
            "description": "UUID of the file or subfolder"
          },
          "encryptedKey": {
            "type": "string",
            "description": "Hex-encoded ECIES ciphertext of the key wrapped with ephemeral public key"
          }
        },
        "required": ["keyType", "itemId", "encryptedKey"]
      },
      "InviteDataResponseDto": {
        "type": "object",
        "properties": {
