          },
          "encryptedKey": {
            "type": "string",
            "description": "Hex-encoded item key wrapped with ephemeral public key"
          },
          "encryptedChildKeys": {
            "description": "Array of child keys wrapped with ephemeral public key, or null",
            "nullable": true,
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/InviteChildKeyDto"
            }
          },
          "itemType": {
            "type": "string",
            "enum": ["folder", "file"]
          },
          "ipnsName": {
            "type": "string",
            "description": "IPNS name of the shared item"
          },
          "itemName": {
