          },
          "itemId": {
            "type": "string",
            "description": "UUID of the file or subfolder"
          },
          "encryptedKey": {
            "type": "string",
            "description": "Hex-encoded ECIES ciphertext of the key re-wrapped for recipient"
          }
        },
        "required": ["keyType", "itemId", "encryptedKey"]
      },
      "ClaimInviteDto": {
        "type": "object",
        "properties": {
