            "description": "Hex-encoded item key re-wrapped for the recipient via ECIES"
          },
          "childKeys": {
            "description": "Re-wrapped child keys for subfolders/files",
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/ClaimChildKeyDto"
            }
          }
        },
        "required": ["encryptedKey"]
      },
      "ClaimInviteResponseDto": {
        "type": "object",
        "properties": {
          "shareId": {
            "type": "string",
            "description": "UUID of the created share"
          }
        },
        "required": ["shareId"]
      },
      "CreateInviteDto": {
        "type": "object",
        "properties": {
