            "type": "array",
            "items": {
              "$ref": "#/components/schemas/InviteChildKeyDto"
            }
          }
        },
        "required": ["itemType", "ipnsName", "itemName", "encryptedKey"]
      },
      "InviteResponseDto": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Invite UUID (for management operations like revoke)"
          },
          "token": {
            "type": "string",
            "description": "Invite token (URL-safe base64)"
          },
          "itemType": {
            "type": "string",
            "enum": ["folder", "file"]
          },
          "ipnsName": {
            "type": "string",
            "description": "IPNS name of the shared item"
          },
          "itemName": {
            "type": "string",
            "description": "Display name of the shared item"
          },
          "status": {
            "type": "string",
            "enum": ["active", "claimed", "revoked"]
          },
          "expiresAt": {
            "type": "string",
            "description": "When the invite expires",
            "format": "date-time"
          },
          "createdAt": {
            "type": "string",
            "description": "When the invite was created",
            "format": "date-time"
          }
        },
        "required": [
          "id",
          "token",
          "itemType",
          "ipnsName",
          "itemName",
          "status",
          "expiresAt",
          "createdAt"
        ]
      },
      "ConnectionTestRequestDto": {
        "type": "object",
        "properties": {
          "encryptedConfig": {
            "type": "string",
            "description": "ECIES-encrypted provider config (hex-encoded)"
          },
          "epoch": {
            "type": "number",
            "description": "TEE epoch for key selection"
          }
        },
        "required": ["encryptedConfig", "epoch"]
      },
      "ConnectionTestResponseDto": {
        "type": "object",
        "properties": {
          "success": {
            "type": "boolean",
            "description": "Whether the connection test succeeded"
          },
          "protocol": {
            "type": "string",
            "enum": ["kubo", "psa"],
            "description": "Detected protocol"
          },
          "version": {
            "type": "string",
            "description": "Provider version string"
          },
          "latencyMs": {
            "type": "number",
            "description": "Probe latency in milliseconds"
          },
          "error": {
            "type": "string",
            "description": "Error message on failure"
          }
        },
        "required": ["success", "latencyMs"]
      }
    }
  }
}

